import { PageShell } from "../../components/layout/PageShell.jsx";
import { Stages } from "../../components/stages/Stages.jsx";

export default function SectionPage({ page }) {
    return (
        <PageShell>
            <h1 className="sr-only">{page.title}</h1>
            <Stages stages={page.stages} />
        </PageShell>
    );
}

export async function getStaticPaths() {
    return { paths: [{ params: { id: "home" } }, { params: { id: "sport" } }], fallback: false };
}

export async function getStaticProps({ params }) {
    const { loadPage } = await import("../../lib/page-props.js");
    return { props: { page: loadPage(params.id === "home" ? "home" : "section") } };
}
