import { createContext, useCallback, useContext, useEffect, useMemo, useState } from "react";
import useEmblaCarousel from "embla-carousel-react";
import clsx from "clsx";
import { Button } from "./primitives.jsx";
import { Icon } from "./icons.jsx";
import { interactionTracking } from "../../lib/tracking.js";
import { Box, Text } from "./ds.jsx";

const SliderContext = createContext(null);

const OPTIONS = { align: "start", containScroll: "trimSnaps", slidesToScroll: 1, skipSnaps: false, watchDrag: true, breakpoints: { "(min-width: 1024px)": { slidesToScroll: 1 } } };

// An Embla carousel. Buttons jump to the next snap without animation frames,
// so a step measures the slide bookkeeping and the re-render, not an
// animation.
export function Slider({ name, label, slideClassName, children, className }) {
    const [viewportRef, api] = useEmblaCarousel(OPTIONS);
    const [state, setState] = useState({ index: 0, canPrev: false, canNext: true, inView: [0, 1, 2] });

    const update = useCallback((embla) => {
        setState({ index: embla.selectedScrollSnap(), canPrev: embla.canScrollPrev(), canNext: embla.canScrollNext(), inView: embla.slidesInView() });
    }, []);

    useEffect(() => {
        if (!api)
            return;
        update(api);
        api.on("select", update).on("reInit", update).on("slidesInView", update);
        return () => {
            api.off("select", update).off("reInit", update).off("slidesInView", update);
        };
    }, [api, update]);

    const prev = useCallback(() => api?.scrollPrev(true), [api]);
    const next = useCallback(() => api?.scrollNext(true), [api]);
    const context = useMemo(() => ({ ...state, name }), [state, name]);
    const slides = Array.isArray(children) ? children : [children];

    return (
        <SliderContext.Provider value={context}>
            <Box className={clsx("group/slider relative", className)} role="region" aria-roledescription="carousel" aria-label={label}>
                <Box className="embla-viewport" ref={viewportRef}>
                    <Box className="embla-container -ml-4">
                        {slides.map((slide, i) => (
                            <SliderSlide key={i} index={i} total={slides.length} className={slideClassName}>{slide}</SliderSlide>
                        ))}
                    </Box>
                </Box>
                <SliderButton direction="prev" onClick={prev} disabled={!state.canPrev} name={name} />
                <SliderButton direction="next" onClick={next} disabled={!state.canNext} name={name} />
                <SliderDots count={slides.length} index={state.index} />
            </Box>
        </SliderContext.Provider>
    );
}

function SliderSlide({ index, total, className, children }) {
    const { inView } = useContext(SliderContext);
    const visible = inView.includes(index);
    return (
        <Box className={clsx("min-w-0 shrink-0 grow-0 pl-4", className)} role="group" aria-roledescription="slide" aria-label={`${index + 1} von ${total}`} data-in-view={visible ? "true" : "false"}>
            {children}
        </Box>
    );
}

function SliderButton({ direction, onClick, disabled, name }) {
    const label = direction === "prev" ? `${name}: zurück` : `${name}: weiter`;
    return (
        <Button
            variant="round"
            aria-label={label}
            onClick={onClick}
            disabled={disabled}
            className={clsx("absolute top-[calc(50%-2.5rem)] z-(--z-teaser-actions)", direction === "prev" ? "-left-5" : "-right-5")}
            {...interactionTracking(`slider-${direction}`, name)}
        >
            <Icon name={direction === "prev" ? "chevronLeft" : "chevronRight"} />
        </Button>
    );
}

function SliderDots({ count, index }) {
    return (
        <Box className="mt-3 flex justify-center gap-1.5" aria-hidden="true">
            {Array.from({ length: count }, (_, i) => (
                <Text key={i} className={clsx("h-1.5 rounded-full transition-all", i === index ? "w-5 bg-brand-600" : "w-1.5 bg-ink-300")} />
            ))}
        </Box>
    );
}
